R["ca3-opaque-cache"] = "#include <stdlib.h>\n#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\ntypedef struct { int key; int val; int used; } slot_t;\ntypedef struct { slot_t *slots; size_t cap; } cache_t;\ncache_t *cache_create(size_t cap) {\n    cache_t *c = malloc(sizeof *c);\n    if (!c) return NULL;\n    c->slots = calloc(cap, sizeof *c->slots);\n    if (!c->slots) { free(c); return NULL; }\n    c->cap = cap;\n    return c;\n}\nint cache_put(cache_t *c, int key, int value) {\n    for (size_t i = 0; i < c->cap; i++) {\n        if (c->slots[i].used && c->slots[i].key == key) { c->slots[i].val = value; return 1; }\n    }\n    for (size_t i = 0; i < c->cap; i++) {\n        if (!c->slots[i].used) { c->slots[i].used = 1; c->slots[i].key = key; c->slots[i].val = value; return 1; }\n    }\n    return 0;\n}\nint *cache_get(cache_t *c, int key) {\n    for (size_t i = 0; i < c->cap; i++) {\n        if (c->slots[i].used && c->slots[i].key == key) return &c->slots[i].val;\n    }\n    return NULL;\n}\nint main(void) { return 0; }";
