W["ca7-hash-linear"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define HT_CAP 16\ntypedef struct { int key; int val; unsigned char state; } ht_ent_t;\nvoid ht_init(ht_ent_t *t) { for (int i = 0; i < HT_CAP; i++) t[i].state = 0; }\nstatic int ht_hash(int key) { return (int)(((unsigned)key * 2654435761u) % HT_CAP); }\nint ht_put(ht_ent_t *t, int key, int val) {\n    int h = ht_hash(key);\n    for (int i = 0; i < HT_CAP; i++) {\n        int idx = (h + i) % HT_CAP;\n        if (t[idx].state != 1) { t[idx].key = key; t[idx].val = val; t[idx].state = 1; return 1; }\n    }\n    return 0;\n}\nint *ht_get(ht_ent_t *t, int key) {\n    int h = ht_hash(key);\n    for (int i = 0; i < HT_CAP; i++) {\n        int idx = (h + i) % HT_CAP;\n        if (t[idx].state == 0) return NULL;\n        if (t[idx].state == 1 && t[idx].key == key) return &t[idx].val;\n    }\n    return NULL;\n}\nint ht_del(ht_ent_t *t, int key) {\n    int h = ht_hash(key);\n    for (int i = 0; i < HT_CAP; i++) {\n        int idx = (h + i) % HT_CAP;\n        if (t[idx].state == 0) return 0;\n        if (t[idx].state == 1 && t[idx].key == key) { t[idx].state = 0; return 1; }\n    }\n    return 0;\n}\nint main(void) { return 0; }";
R["ca7-heap"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\ntypedef struct { int a[64]; size_t n; } heap_t;\nstatic void sift_up(heap_t *h, size_t i) {\n    while (i > 0) {\n        size_t p = (i - 1) / 2;\n        if (h->a[p] <= h->a[i]) break;\n        int t = h->a[p]; h->a[p] = h->a[i]; h->a[i] = t;\n        i = p;\n    }\n}\nstatic void sift_down(heap_t *h, size_t i) {\n    for (;;) {\n        size_t l = 2 * i + 1, r = 2 * i + 2, m = i;\n        if (l < h->n && h->a[l] < h->a[m]) m = l;\n        if (r < h->n && h->a[r] < h->a[m]) m = r;\n        if (m == i) break;\n        int t = h->a[m]; h->a[m] = h->a[i]; h->a[i] = t;\n        i = m;\n    }\n}\nvoid heap_push(heap_t *h, int v) { h->a[h->n] = v; h->n++; sift_up(h, h->n - 1); }\nint heap_pop(heap_t *h) {\n    int min = h->a[0];\n    h->a[0] = h->a[h->n - 1];\n    h->n--;\n    sift_down(h, 0);\n    return min;\n}\nint heap_min(const heap_t *h) { return h->a[0]; }\nint main(void) { return 0; }";
