R["ca7-union-find"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nvoid uf_init(int *parent, int *rank_, int n) {\n    for (int i = 0; i < n; i++) { parent[i] = i; rank_[i] = 0; }\n}\nint uf_find(int *parent, int x) {\n    int r = x;\n    while (parent[r] != r) r = parent[r];\n    while (parent[x] != r) { int nx = parent[x]; parent[x] = r; x = nx; }\n    return r;\n}\nvoid uf_union(int *parent, int *rank_, int a, int b) {\n    int ra = uf_find(parent, a);\n    int rb = uf_find(parent, b);\n    if (ra == rb) return;\n    if (rank_[ra] < rank_[rb]) { int t = ra; ra = rb; rb = t; }\n    parent[rb] = ra;\n    if (rank_[ra] == rank_[rb]) rank_[ra]++;\n}\nint uf_connected(int *parent, int a, int b) { return uf_find(parent, a) == uf_find(parent, b) ? 1 : 0; }\nint main(void) { return 0; }";
W["ca7-union-find"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nvoid uf_init(int *parent, int *rank_, int n) {\n    for (int i = 0; i < n; i++) { parent[i] = i; rank_[i] = 0; }\n}\nint uf_find(int *parent, int x) {\n    while (parent[x] != x) x = parent[x];\n    return x;\n}\nvoid uf_union(int *parent, int *rank_, int a, int b) {\n    int ra = uf_find(parent, a);\n    int rb = uf_find(parent, b);\n    if (ra == rb) return;\n    parent[rb] = ra;\n    (void)rank_;\n}\nint uf_connected(int *parent, int a, int b) { return uf_find(parent, a) == uf_find(parent, b) ? 1 : 0; }\nint main(void) { return 0; }";
R["ca7-csr"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nvoid csr_build(int V, const int (*edges)[2], size_t E, int *offset, int *adj) {\n    for (int v = 0; v <= V; v++) offset[v] = 0;\n    for (size_t i = 0; i < E; i++) offset[edges[i][0] + 1]++;\n    for (int v = 0; v < V; v++) offset[v + 1] += offset[v];\n    int *cur = offset; /* reuse: cur[v] = next write pos */\n    int tmp[64];\n    for (int v = 0; v <= V; v++) tmp[v] = offset[v];\n    for (size_t i = 0; i < E; i++) adj[tmp[edges[i][0]]++] = edges[i][1];\n    (void)cur;\n}\nint main(void) { return 0; }";
