R["ca8-bytesort"] = "#include <string.h>\n#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nint cmp_int(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);\n}\ntypedef struct { int key; int seq; } rec_t;\nint cmp_rec_key(const void *a, const void *b) {\n    int x = ((const rec_t *)a)->key, y = ((const rec_t *)b)->key;\n    return (x > y) - (x < y);\n}\nvoid isort(void *base, size_t n, size_t size, int (*cmp)(const void *, const void *)) {\n    unsigned char tmp[64];\n    unsigned char *b = base;\n    for (size_t i = 1; i < n; i++) {\n        memcpy(tmp, b + i * size, size);\n        size_t j = i;\n        while (j > 0 && cmp(b + (j - 1) * size, tmp) > 0) {\n            memcpy(b + j * size, b + (j - 1) * size, size);\n            j--;\n        }\n        memcpy(b + j * size, tmp, size);\n    }\n}\nint main(void) { return 0; }";
