R["ca8-checkpoint-generic"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#include <string.h>\ntypedef struct { unsigned char tag; int key; } item_t;\nvoid item_sort(item_t *a, size_t n) {\n    unsigned char tmp[sizeof(item_t)];\n    for (size_t i = 1; i < n; i++) {\n        memcpy(tmp, &a[i], sizeof(item_t));\n        size_t j = i;\n        while (j > 0 && a[j - 1].key > ((item_t *)tmp)->key) {\n            memcpy(&a[j], &a[j - 1], sizeof(item_t));\n            j--;\n        }\n        memcpy(&a[j], tmp, sizeof(item_t));\n    }\n}\nconst char *item_describe(const item_t *v) {\n    if (!v) return NULL;\n    if (v->tag == 1) return \"int-like\";\n    if (v->tag == 2) return \"double-like\";\n    return NULL;\n}\nsize_t item_count_tag(const item_t *a, size_t n, unsigned char tag) {\n    size_t c = 0;\n    for (size_t i = 0; i < n; i++) {\n        if (a[i].tag == tag) c++;\n    }\n    return c;\n}\nint main(void) { return 0; }";
