R["ca7-hash-linear"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define HT_CAP 16\ntypedef struct { int key; int val; unsigned char state; } ht_ent_t;\nvoid ht_init(ht_ent_t *t) { for (int i = 0; i < HT_CAP; i++) t[i].state = 0; }\nstatic int ht_hash(int key) { return (int)(((unsigned)key * 2654435761u) % HT_CAP); }\nint ht_put(ht_ent_t *t, int key, int val) {\n    int h = ht_hash(key);\n    int tomb = -1;\n    for (int i = 0; i < HT_CAP; i++) {\n        int idx = (h + i) % HT_CAP;\n        if (t[idx].state == 0) { idx = (tomb >= 0) ? tomb : idx; t[idx].key = key; t[idx].val = val; t[idx].state = 1; return 1; }\n        if (t[idx].state == 2 && tomb < 0) tomb = idx;\n        if (t[idx].state == 1 && t[idx].key == key) { t[idx].val = val; return 1; }\n    }\n    if (tomb >= 0) { t[tomb].key = key; t[tomb].val = val; t[tomb].state = 1; return 1; }\n    return 0;\n}\nint *ht_get(ht_ent_t *t, int key) {\n    int h = ht_hash(key);\n    for (int i = 0; i < HT_CAP; i++) {\n        int idx = (h + i) % HT_CAP;\n        if (t[idx].state == 0) return NULL;\n        if (t[idx].state == 1 && t[idx].key == key) return &t[idx].val;\n    }\n    return NULL;\n}\nint ht_del(ht_ent_t *t, int key) {\n    int h = ht_hash(key);\n    for (int i = 0; i < HT_CAP; i++) {\n        int idx = (h + i) % HT_CAP;\n        if (t[idx].state == 0) return 0;\n        if (t[idx].state == 1 && t[idx].key == key) { t[idx].state = 2; return 1; }\n    }\n    return 0;\n}\nint main(void) { return 0; }";
