R["ca15-checkpoint-ring"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nstruct ring { int buf[8]; size_t head, tail, count; };\nbool ring_size_ok(const struct ring *r) { return r->count <= 8 && r->head < 8 && r->tail < 8; }\nbool ring_count_matches(const struct ring *r, size_t expected) {\n    (void)expected;\n    return r->count <= 8 && r->head < 8 && r->tail < 8 && (r->count != 0 || r->head == r->tail);\n}\nconst char *diagnose(const struct ring *r) {\n    if (r->head >= 8 || r->tail >= 8) return \"index-corrupt\";\n    if (r->count > 8) return \"size-corrupt\";\n    return \"ok\";\n}\nint main(void) { return 0; }";
