R["ca17-exit-status-decode"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/wait.h>\n#include <fcntl.h>\n#include <signal.h>\n#include <string.h>\n#include <errno.h>\nstatic int run_exit_status(int code) {\n    pid_t p = fork();\n    if (p < 0) return -1;\n    if (p == 0) _exit(code);\n    int st = 0;\n    if (waitpid(p, &st, 0) < 0) return -1;\n    return st;\n}\nint decode_exit(int status) {\n    if (WIFEXITED(status)) return WEXITSTATUS(status);\n    return -1;\n}\nint main(void) { return 0; }";
