R["ca17-pipe-echo-capture"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/wait.h>\n#include <fcntl.h>\n#include <signal.h>\n#include <string.h>\n#include <errno.h>\nint capture_child(const char *cmd, char *out, size_t cap) {\n    if (cmd == NULL || out == NULL || cap == 0) return -1;\n    int fds[2];\n    if (pipe(fds) != 0) return -1;\n    pid_t p = fork();\n    if (p < 0) { close(fds[0]); close(fds[1]); return -1; }\n    if (p == 0) {\n        close(fds[0]);\n        dup2(fds[1], STDOUT_FILENO);\n        close(fds[1]);\n        execl('/bin/sh', 'sh', '-c', cmd, (char *)NULL);\n        _exit(127);\n    }\n    close(fds[1]);\n    size_t got = 0;\n    for (;;) {\n        char chunk[64];\n        ssize_t n = read(fds[0], chunk, sizeof chunk);\n        if (n <= 0) break;\n        for (ssize_t i = 0; i < n && got + 1 < cap; i++) out[got++] = chunk[i];\n        if (got + 1 >= cap) break;\n    }\n    out[got] = 0;\n    close(fds[0]);\n    int st = 0;\n    waitpid(p, &st, 0);\n    if (!WIFEXITED(st)) return -1;\n    return WEXITSTATUS(st);\n}\nint main(void) { return 0; }";
