R["ca17-checkpoint-jobs"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/wait.h>\n#include <fcntl.h>\n#include <signal.h>\n#include <string.h>\n#include <errno.h>\nstatic int run_capture(const char *cmd) {\n    pid_t p = fork();\n    if (p < 0) return -1;\n    if (p == 0) {\n        int dn = open(\"/dev/null\", O_WRONLY);\n        if (dn >= 0) { dup2(dn, STDOUT_FILENO); dup2(dn, STDERR_FILENO); }\n        execl(\"/bin/sh\", \"sh\", \"-c\", cmd, (char *)NULL);\n        _exit(127);\n    }\n    int st = 0;\n    if (waitpid(p, &st, 0) < 0) return -1;\n    if (!WIFEXITED(st)) return -1;\n    return WEXITSTATUS(st);\n}\nsize_t run_sequence(const char *const *cmds, size_t n, int *codes) {\n    if (cmds == NULL && n > 0) return (size_t)-1;\n    size_t failures = 0;\n    for (size_t i = 0; i < n; i++) {\n        int rc = run_capture(cmds[i]);\n        if (codes != NULL) codes[i] = rc;\n        if (rc != 0) failures++;\n    }\n    return failures;\n}\nint main(void) { return 0; }";
