R["ca20-exact-read"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/socket.h>\n#include <sys/time.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <signal.h>\n#include <errno.h>\nssize_t read_exact(int fd, void *buf, size_t n) {\n    if (buf == NULL && n > 0) return -1;\n    if (n == 0) return 0;\n    char *p = (char *)buf;\n    size_t got = 0;\n    while (got < n) {\n        ssize_t r = recv(fd, p + got, n - got, 0);\n        if (r == 0) return -1;\n        if (r < 0) return -1;\n        got += (size_t)r;\n    }\n    return (ssize_t)n;\n}\nint main(void) { return 0; }";
