W["ca20-exact-read"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/socket.h>\n#include <sys/time.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <signal.h>\n#include <errno.h>\nssize_t read_exact(int fd, void *buf, size_t n) {\n    if (buf == NULL && n > 0) return -1;\n    if (n == 0) return -1;\n    char *p = (char *)buf;\n    ssize_t r = recv(fd, p, n, 0);\n    if (r <= 0) return 0;\n    return r - 1;\n    return (ssize_t)n;\n}\nint main(void) { return 0; }";
R["ca20-udp-roundtrip"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/socket.h>\n#include <sys/time.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <signal.h>\n#include <errno.h>\nssize_t udp_roundtrip(int ufd, const char *msg, char *out, size_t cap) {\n    if (ufd < 0 || msg == NULL || out == NULL || cap == 0) return -1;\n    struct sockaddr_in self;\n    socklen_t sl = sizeof self;\n    if (getsockname(ufd, (struct sockaddr *)&self, &sl) != 0) return -1;\n    size_t mlen = strlen(msg);\n    if (sendto(ufd, msg, mlen, 0, (struct sockaddr *)&self, sizeof self) != (ssize_t)mlen) return -1;\n    ssize_t n = recvfrom(ufd, out, cap - 1, 0, NULL, NULL);\n    if (n < 0) return -1;\n    out[n] = 0;\n    return n;\n}\nint main(void) { return 0; }";
W["ca20-udp-roundtrip"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/socket.h>\n#include <sys/time.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <signal.h>\n#include <errno.h>\nssize_t udp_roundtrip(int ufd, const char *msg, char *out, size_t cap) {\n    if (ufd < 0 || msg == NULL || out == NULL || cap == 0) return -1;\n    struct sockaddr_in self;\n    socklen_t sl = sizeof self;\n    if (getsockname(ufd, (struct sockaddr *)&self, &sl) != 0) return -1;\n    size_t mlen = strlen(msg);\n    if (sendto(ufd, msg, mlen, 0, (struct sockaddr *)&self, sizeof self) != (ssize_t)mlen) return -1;\n    ssize_t n = recvfrom(ufd, out, cap - 1, 0, NULL, NULL);\n    if (n < 0) return -1;\n    out[0] = 0;\n    return mlen;\n}\nint main(void) { return 0; }";
R["ca20-checkpoint-echo"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/socket.h>\n#include <sys/time.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <signal.h>\n#include <errno.h>\n#include <pthread.h>\nstruct serve_arg {\n    int lfd;\n};\nstatic int make_loopback_listener(void) {\n    int fd = socket(AF_INET, SOCK_STREAM, 0);\n    if (fd < 0) return -1;\n    struct sockaddr_in sa;\n    memset(&sa, 0, sizeof sa);\n    sa.sin_family = AF_INET;\n    sa.sin_addr.s_addr = htonl(INADDR_LOOPBACK);\n    sa.sin_port = 0;\n    if (bind(fd, (struct sockaddr *)&sa, sizeof sa) != 0) { close(fd); return -1; }\n    if (listen(fd, 16) != 0) { close(fd); return -1; }\n    return fd;\n};\nstatic int connect_to_listener(int lfd) {\n    struct sockaddr_in sa;\n    socklen_t sl = sizeof sa;\n    if (getsockname(lfd, (struct sockaddr *)&sa, &sl) != 0) return -1;\n    int cfd = socket(AF_INET, SOCK_STREAM, 0);\n    if (cfd < 0) return -1;\n    if (connect(cfd, (struct sockaddr *)&sa, sizeof sa) != 0) { close(cfd); return -1; }\n    return cfd;\n};\nint echo_serve(int lfd) {\n    if (lfd < 0) return -1;\n    int cfd = accept(lfd, NULL, NULL);\n    if (cfd < 0) return -1;\n    char buf[256];\n    ssize_t n;\n    while ((n = recv(cfd, buf, sizeof buf, 0)) > 0) {\n        ssize_t off = 0;\n        while (off < n) {\n            ssize_t w = send(cfd, buf + off, (size_t)(n - off), 0);\n            if (w <= 0) break;\n            off += w;\n        }\n    }\n    close(cfd);\n    return 0;\n};\nstatic void *serve_thread(void *arg) {\n    struct serve_arg *a = (struct serve_arg *)arg;\n    echo_serve(a->lfd);\n    return NULL;\n};\nint main(void) { return 0; }\n";
W["ca20-checkpoint-echo"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <sys/socket.h>\n#include <sys/time.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <signal.h>\n#include <errno.h>\n#include <pthread.h>\nstruct serve_arg {\n    int lfd;\n};\nstatic int make_loopback_listener(void) {\n    int fd = socket(AF_INET, SOCK_STREAM, 0);\n    if (fd < 0) return -1;\n    struct sockaddr_in sa;\n    memset(&sa, 0, sizeof sa);\n    sa.sin_family = AF_INET;\n    sa.sin_addr.s_addr = htonl(INADDR_LOOPBACK);\n    sa.sin_port = 0;\n    if (bind(fd, (struct sockaddr *)&sa, sizeof sa) != 0) { close(fd); return -1; }\n    if (listen(fd, 16) != 0) { close(fd); return -1; }\n    return fd;\n};\nstatic int connect_to_listener(int lfd) {\n    struct sockaddr_in sa;\n    socklen_t sl = sizeof sa;\n    if (getsockname(lfd, (struct sockaddr *)&sa, &sl) != 0) return -1;\n    int cfd = socket(AF_INET, SOCK_STREAM, 0);\n    if (cfd < 0) return -1;\n    if (connect(cfd, (struct sockaddr *)&sa, sizeof sa) != 0) { close(cfd); return -1; }\n    return cfd;\n};\nint echo_serve(int lfd) {\n    if (lfd < 0) return -1;\n    int cfd = accept(lfd, NULL, NULL);\n    if (cfd < 0) return -1;\n    char buf[256];\n    ssize_t n = recv(cfd, buf, sizeof buf, 0);\n    if (n > 0) {\n        memset(buf, 88, (size_t)n);\n        send(cfd, buf, (size_t)n, 0);\n    }\n    close(cfd);\n    return 0;\n};\nstatic void *serve_thread(void *arg) {\n    struct serve_arg *a = (struct serve_arg *)arg;\n    echo_serve(a->lfd);\n    return NULL;\n};\nint main(void) { return 0; }\n";
R["ca21-gather-spans"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nstruct span { const char *base; size_t len; };\nsize_t spans_total(const struct span *s, size_t n) {\n    if (s == NULL) return n == 0 ? 0 : (size_t)-1;\n    size_t t = 0;\n    for (size_t i = 0; i < n; i++) t += s[i].len;\n    return t;\n}\nvoid spans_gather(const struct span *s, size_t n, char *out) {\n    if (s == NULL || out == NULL) return;\n    size_t k = 0;\n    for (size_t i = 0; i < n; i++) {\n        if (s[i].base == NULL) continue;\n        for (size_t j = 0; j < s[i].len; j++) out[k++] = s[i].base[j];\n    }\n    out[k] = 0;\n}\nint main(void) { return 0; }";
W["ca21-gather-spans"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nstruct span { const char *base; size_t len; };\nsize_t spans_total(const struct span *s, size_t n) {\n    if (s == NULL) return n == 0 ? 0 : (size_t)-1;\n    size_t t = 0;\n    for (size_t i = 0; i < n; i++) t += s[i].len;\n    return t;\n}\nvoid spans_gather(const struct span *s, size_t n, char *out) {\n    if (s == NULL || out == NULL) return;\n    size_t k = 0;\n    for (size_t i = n; i-- > 0;) {\n        if (s[i].base == NULL) continue;\n        for (size_t j = 0; j < s[i].len; j++) out[k++] = s[i].base[j];\n    }\n    out[k] = 0;\n}\nint main(void) { return 0; }";
R["ca21-buffered-writer"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nstruct bw { char buf[64]; size_t n; int flushes; };\nvoid bw_write(struct bw *w, const char *s, size_t len) {\n    if (w == NULL || s == NULL || len == 0) return;\n    for (size_t i = 0; i < len; i++) {\n        if (w->n == 64) {\n            w->flushes++;\n            w->n = 0;\n        }\n        w->buf[w->n++] = s[i];\n    }\n}\nsize_t bw_pending(const struct bw *w) {\n    return w == NULL ? 0 : w->n;\n}\nint main(void) { return 0; }";
W["ca21-buffered-writer"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nstruct bw { char buf[64]; size_t n; int flushes; };\nvoid bw_write(struct bw *w, const char *s, size_t len) {\n    if (w == NULL || s == NULL || len == 0) return;\n    for (size_t i = 0; i < len; i++) {\n        w->buf[w->n++] = s[i];\n        if (w->n >= 8) {\n            w->flushes++;\n            w->n = 0;\n        }\n    }\n}\nsize_t bw_pending(const struct bw *w) {\n    return w == NULL ? 0 : w->n;\n}\nint main(void) { return 0; }";
R["ca21-mmap-sum"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/uio.h>\n#include <time.h>\n#include <errno.h>\nstatic const char *GIVEN_PATTERN_PATH = \"/tmp/cj_ca21_pattern.bin\";\nstatic long make_pattern_file(void) {\n    int fd = open(GIVEN_PATTERN_PATH, O_RDWR | O_CREAT | O_TRUNC, 0600);\n    if (fd < 0) return -1;\n    unsigned char byte[256];\n    for (int i = 0; i < 256; i++) byte[i] = (unsigned char)i;\n    for (int r = 0; r < 16; r++) {\n        if (write(fd, byte, 256) != 256) { close(fd); return -1; }\n    }\n    close(fd);\n    return 0;\n}\nlong sum_bytes_mmap(const char *path) {\n    if (path == NULL) return -1;\n    int fd = open(path, O_RDONLY);\n    if (fd < 0) return -1;\n    struct stat st;\n    if (fstat(fd, &st) != 0) { close(fd); return -1; }\n    if (st.st_size == 0) { close(fd); return 0; }\n    void *mp = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);\n    if (mp == MAP_FAILED) { close(fd); return -1; }\n    const unsigned char *p = (const unsigned char *)mp;\n    long total = 0;\n    for (off_t i = 0; i < st.st_size; i++) total += p[i];\n    munmap(mp, (size_t)st.st_size);\n    close(fd);\n    return total;\n}\nint main(void) { return 0; }";
W["ca21-mmap-sum"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/uio.h>\n#include <time.h>\n#include <errno.h>\nstatic const char *GIVEN_PATTERN_PATH = \"/tmp/cj_ca21_pattern.bin\";\nstatic long make_pattern_file(void) {\n    int fd = open(GIVEN_PATTERN_PATH, O_RDWR | O_CREAT | O_TRUNC, 0600);\n    if (fd < 0) return -1;\n    unsigned char byte[256];\n    for (int i = 0; i < 256; i++) byte[i] = (unsigned char)i;\n    for (int r = 0; r < 16; r++) {\n        if (write(fd, byte, 256) != 256) { close(fd); return -1; }\n    }\n    close(fd);\n    return 0;\n}\nlong sum_bytes_mmap(const char *path) {\n    if (path == NULL) return -1;\n    int fd = open(path, O_RDONLY);\n    if (fd < 0) return -1;\n    struct stat st;\n    if (fstat(fd, &st) != 0) { close(fd); return -1; }\n    if (st.st_size == 0) { close(fd); return 0; }\n    void *mp = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);\n    if (mp == MAP_FAILED) { close(fd); return -1; }\n    const unsigned char *p = (const unsigned char *)mp;\n    long total = 0;\n    for (off_t i = 0; i < st.st_size - 1; i++) total += p[i];\n    munmap(mp, (size_t)st.st_size);\n    close(fd);\n    return total;\n}\nint main(void) { return 0; }";
R["ca21-checkpoint-lines"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/uio.h>\n#include <time.h>\n#include <errno.h>\nstatic const char *GIVEN_LINES_PATH = \"/tmp/cj_ca21_lines.txt\";\nstatic long make_lines_file(long n) {\n    int fd = open(GIVEN_LINES_PATH, O_RDWR | O_CREAT | O_TRUNC, 0600);\n    if (fd < 0) return -1;\n    for (long i = 0; i < n; i++) {\n        if (write(fd, \"line.\\n\", 6) != 6) { close(fd); return -1; }\n    }\n    close(fd);\n    return 0;\n}\nlong count_lines_mmap(const char *path) {\n    if (path == NULL) return -1;\n    int fd = open(path, O_RDONLY);\n    if (fd < 0) return -1;\n    struct stat st;\n    if (fstat(fd, &st) != 0) { close(fd); return -1; }\n    if (st.st_size == 0) { close(fd); return 0; }\n    void *mp = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);\n    if (mp == MAP_FAILED) { close(fd); return -1; }\n    const char *p = (const char *)mp;\n    long lines = 0;\n    for (off_t i = 0; i < st.st_size; i++) {\n        if (p[i] == 10) lines++;\n    }\n    munmap(mp, (size_t)st.st_size);\n    close(fd);\n    return lines;\n}\nint main(void) { return 0; }";
W["ca21-checkpoint-lines"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/uio.h>\n#include <time.h>\n#include <errno.h>\nstatic const char *GIVEN_LINES_PATH = \"/tmp/cj_ca21_lines.txt\";\nstatic long make_lines_file(long n) {\n    int fd = open(GIVEN_LINES_PATH, O_RDWR | O_CREAT | O_TRUNC, 0600);\n    if (fd < 0) return -1;\n    for (long i = 0; i < n; i++) {\n        if (write(fd, \"line.\\n\", 6) != 6) { close(fd); return -1; }\n    }\n    close(fd);\n    return 0;\n}\nlong count_lines_mmap(const char *path) {\n    if (path == NULL) return -1;\n    int fd = open(path, O_RDONLY);\n    if (fd < 0) return -1;\n    struct stat st;\n    if (fstat(fd, &st) != 0) { close(fd); return -1; }\n    if (st.st_size == 0) { close(fd); return 0; }\n    void *mp = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);\n    if (mp == MAP_FAILED) { close(fd); return -1; }\n    const char *p = (const char *)mp;\n    long lines = 0;\n    for (off_t i = 0; i < st.st_size; i++) {\n        if (p[i] != 10) lines++;\n    }\n    munmap(mp, (size_t)st.st_size);\n    close(fd);\n    return lines;\n}\nint main(void) { return 0; }";
