R["ca22-blocked-transpose"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\nvoid transpose_blocked(int *dst, const int *src, size_t n, size_t block) {\n    if (dst == NULL || src == NULL || n == 0) return;\n    if (block == 0) block = 1;\n    for (size_t bi = 0; bi < n; bi += block) {\n        size_t iend = bi + block < n ? bi + block : n;\n        for (size_t bj = 0; bj < n; bj += block) {\n            size_t jend = bj + block < n ? bj + block : n;\n            for (size_t i = bi; i < iend; i++) {\n                for (size_t j = bj; j < jend; j++) {\n                    dst[j * n + i] = src[i * n + j];\n                }\n            }\n        }\n    }\n}\nint main(void) { return 0; }";
