R["ca21-mmap-sum"] = "#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#define _POSIX_C_SOURCE 200809L\n#include <unistd.h>\n#include <fcntl.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/uio.h>\n#include <time.h>\n#include <errno.h>\nstatic const char *GIVEN_PATTERN_PATH = \"/tmp/cj_ca21_pattern.bin\";\nstatic long make_pattern_file(void) {\n    int fd = open(GIVEN_PATTERN_PATH, O_RDWR | O_CREAT | O_TRUNC, 0600);\n    if (fd < 0) return -1;\n    unsigned char byte[256];\n    for (int i = 0; i < 256; i++) byte[i] = (unsigned char)i;\n    for (int r = 0; r < 16; r++) {\n        if (write(fd, byte, 256) != 256) { close(fd); return -1; }\n    }\n    close(fd);\n    return 0;\n}\nlong sum_bytes_mmap(const char *path) {\n    if (path == NULL) return -1;\n    int fd = open(path, O_RDONLY);\n    if (fd < 0) return -1;\n    struct stat st;\n    if (fstat(fd, &st) != 0) { close(fd); return -1; }\n    if (st.st_size == 0) { close(fd); return 0; }\n    void *mp = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);\n    if (mp == MAP_FAILED) { close(fd); return -1; }\n    const unsigned char *p = (const unsigned char *)mp;\n    long total = 0;\n    for (off_t i = 0; i < st.st_size; i++) total += p[i];\n    munmap(mp, (size_t)st.st_size);\n    close(fd);\n    return total;\n}\nint main(void) { return 0; }";
